// Some portions generated by Codex
package org.eclipse.rdf4j.workbench.commands;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.common.iteration.CloseableIteratorIteration;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.Test;

class NativeQueryResultBagWitnessTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void witnessesSeveralProjectedCandidatesAndMultiplicityWithOneEarlyClosedStream() {
		BindingSet a = binding("source", "urn:a");
		BindingSet b = binding("source", "urn:b");
		List<BindingSet> actual = List.of(a, a, b, b);
		List<BindingSet> reference = List.of(binding("source", "urn:ignored"), a, b, a, b,
				binding("source", "urn:after"));
		AtomicInteger opens = new AtomicInteger();
		AtomicInteger consumed = new AtomicInteger();
		AtomicInteger closes = new AtomicInteger();

		NativeQueryResultBagWitness.assertContained(actual, () -> {
			opens.incrementAndGet();
			return new CloseableIteratorIteration<>(reference.iterator()) {
				@Override
				public BindingSet next() {
					consumed.incrementAndGet();
					return super.next();
				}

				@Override
				protected void handleClose() {
					closes.incrementAndGet();
				}
			};
		}, "multiple candidates");

		assertThat(opens).hasValue(1);
		assertThat(consumed).hasValue(5);
		assertThat(closes).hasValue(1);
	}

	@Test
	void rejectsAnAbsentCandidate() {
		BindingSet a = binding("source", "urn:a");
		BindingSet missing = binding("source", "urn:missing");

		assertThatThrownBy(() -> NativeQueryResultBagWitness.assertContained(List.of(a, missing),
				() -> new CloseableIteratorIteration<>(List.of(a, binding("source", "urn:b")).iterator()),
				"absent candidate"))
						.isInstanceOf(AssertionError.class)
						.hasMessageContaining("urn:missing");
	}

	@Test
	void rejectsAnOverrepresentedCandidate() {
		BindingSet a = binding("source", "urn:a");

		assertThatThrownBy(() -> NativeQueryResultBagWitness.assertContained(List.of(a, a),
				() -> new CloseableIteratorIteration<>(List.of(a).iterator()), "overrepresented candidate"))
						.isInstanceOf(AssertionError.class)
						.hasMessageContaining("urn:a");
	}

	@Test
	void witnessesDistinctProjectedRowsWithoutPrebinding() {
		String projected = "SELECT DISTINCT ?source WHERE { "
				+ "VALUES (?source ?unprojected) { (<urn:a> 1) (<urn:a> 2) (<urn:b> 1) } }";
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			List<BindingSet> actual;
			try (TupleQueryResult results = connection.prepareTupleQuery(QueryLanguage.SPARQL,
					projected + " LIMIT 2").evaluate()) {
				actual = QueryResults.asList(results);
			}
			AtomicInteger opens = new AtomicInteger();
			NativeQueryResultBagWitness.assertContained(actual, () -> {
				opens.incrementAndGet();
				return connection.prepareTupleQuery(QueryLanguage.SPARQL, projected).evaluate();
			}, "DISTINCT projected rows");
			assertThat(actual).hasSize(2);
			assertThat(actual).allSatisfy(row -> assertThat(row.getBindingNames()).containsExactly("source"));
			assertThat(opens).hasValue(1);
		} finally {
			repository.shutDown();
		}
	}

	private static BindingSet binding(String name, String value) {
		MapBindingSet bindingSet = new MapBindingSet(1);
		bindingSet.addBinding(name, VF.createIRI(value));
		return bindingSet;
	}
}
